INSERT INTO public.projects (id, title, description, full_description, category, techs, github_url, demo_url, image_url, featured, visible, "position", created_at) VALUES ('079dccac-c9cb-4e2e-9502-c497cbc918b7', 'Milagres Transparente', 'Site Oficial da agencia Milagres Transparente', 'O Milagres Transparente é uma aplicação web (Single Page Application - SPA) desenvolvida para a agência de turismo homônima situada em São Miguel dos Milagres, Alagoas.

A plataforma apresenta os roteiros turísticos, mídias reais de clientes e converte o tráfego de visitantes em atendimentos imediatos via WhatsApp, com mensagens personalizadas pré-preenchidas para cada passeio.', 'Frontend', ARRAY['React','Tailwind CSS','vite JavaScript'], '', 'https://milagres-transparente.vercel.app/', 'https://raw.githubusercontent.com/leonardonasls-stack/milagres/refs/heads/main/src/assets/images/brand/logo_principal.webp?token=GHSAT0AAAAAAEIHHI5SLFG2V2UTLNGVFZIG2V5GCWQ', false, true, 2, '2026-09-30 15:55:18.361149+00'), ('3562f4be-c35e-4047-9a84-655c308987a0', 'LLSystem v3 — Sistema de Ordens de Serviço & Gestão Multi-Tenant', ' Sistema completo de gerenciamento de assistência técnica e gestão multi-tenant com API REST assíncrona, frontend web, integração com WhatsApp, geração de PDFs, armazenamento de fotos e controle financeiro.', 'O LLSystem v3 é uma plataforma moderna para gestão de Ordens de Serviço (OS) e empresas licenciadas (Multi-Tenant). O sistema gerencia todo o ciclo de vida operacional de uma assistência técnica — da abertura ao pagamento —, oferece suporte a múltiplos tenants isolados, notificações automáticas via WhatsApp, portal de acompanhamento para clientes e console global para o Superadmin.', 'Frontend', ARRAY['FastAPI + Python 3.12 (async)','MySQL 8.0 via SQLAlchemy 2.0 + aiomysql','HTML5 / TailwindCSS / Vanilla JS servido via FastAPI/Jinja2'], '', null, 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80', false, true, 5, '2026-09-30 16:02:57.622891+00'), ('ce6cc9c1-1256-4ce0-9887-dff53f951ab5', 'Gerador-de-OS-e-recibo', 'O Gerador de OS é uma aplicação web progressiva (PWA) voltada para prestadores de serviço, técnicos e pequenas empresas que precisam emitir Ordens de Serviço profissionais de forma rápida e organizada.', '', 'Fullstack', ARRAY['React','Tailwind CSS','JavaScript'], 'https://github.com/leonardonasls-stack/Gerador-de-OS-e-recibo', 'https://gerador-de-os-e-recibo.vercel.app', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80', false, true, 1, '2026-09-29 03:41:24.052715+00'), ('d2b24c51-fd20-46da-9a39-0549be502820', 'billy-assistente-financeiro', 'Aplicativo de gestão financeira com React Native e Expo.', '', 'Mobile', ARRAY['React','Tailwind CSS','TypeScript'], 'https://github.com/leonardonasls-stack/billy-assistente-financeiro', null, 'https://raw.githubusercontent.com/leonardonasls-stack/billy-assistente-financeiro/refs/heads/main/assets/logo.png', false, true, 0, '2026-09-29 03:37:17.352238+00'), ('da38e0c9-639c-4c51-97ef-c232e3ace23b', 'Console-Telegram-Bot', 'Bot para gerenciar container no docker e Tunel ngrok', '', 'Backend', ARRAY['React','Tailwind CSS','Python'], 'https://github.com/leonardonasls-stack/Console-Telegram-Bot', null, 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80', false, true, 3, '2026-09-30 15:56:48.27912+00'), ('e7c609ec-049e-439a-bc71-f2cd1eacd99a', 'LLSystem PDV ', 'Sistema moderno, ágil e autônomo de Ponto de Venda (PDV) e Frente de Caixa construído com Arquitetura SaaS Multi-Tenant Defense-in-Dept', 'O sistema foi desenvolvido para funcionar como PWA. Com foco em pequenos negociantes como, depositos de bebias, mercearias ou lojas de produtos iniciantes.', 'Fullstack', ARRAY['FastAPI (100% async) + SQLAlchemy 2.0 (asyncpg / psycopg2) + Alembic + JWT + Pydantic v'], '', null, 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80', false, true, 6, '2026-09-30 16:06:47.148784+00');